 "connections.importMetrics": {
  "id": "connections.importMetrics",
  "tag": "connections",
  "name": "importMetrics",
  "method": "POST",
  "path": "/v1/connections/{id}/import-metrics",
  "summary": "Import daily campaign metrics (CSV or rows) into a manual, no-API connection",
  "pathParams": [
   {
    "name": "id",
    "required": true,
    "schema": {
     "type": "string"
    }
   }
  ],
  "query": [],
  "body": {
   "required": true,
   "schema": {
    "type": "object",
    "properties": {
     "csv": {
      "description": "CSV text; give exactly one of csv or rows",
      "type": "string",
      "maxLength": 5000000
     },
     "rows": {
      "description": "one daily row per campaign; campaign_id or campaign_name is required",
      "maxItems": 20000,
      "type": "array",
      "items": {
       "type": "object",
       "properties": {
        "date": {
         "type": "string",
         "description": "YYYY-MM-DD"
        },
        "campaign_id": {
         "type": "string"
        },
        "campaign_name": {
         "type": "string"
        },
        "spend_micros": {
         "type": "integer",
         "minimum": 0,
         "maximum": 9007199254740991
        },
        "currency": {
         "type": "string",
         "description": "ISO-4217"
        },
        "impressions": {
         "type": "integer",
         "minimum": 0,
         "maximum": 9007199254740991
        },
        "clicks": {
         "type": "integer",
         "minimum": 0,
         "maximum": 9007199254740991
        },
        "conversions": {
         "type": "number",
         "minimum": 0
        },
        "revenue_micros": {
         "type": "integer",
         "minimum": 0,
         "maximum": 9007199254740991
        }
       },
       "required": [
        "date",
        "spend_micros",
        "currency"
       ]
      }
     }
    },
    "description": "exactly one of csv or rows"
   }
  },
  "idempotent": true,
  "dryRun": false,
  "auth": true,
  "response": "json"
 },
